import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    'rel': 'http://schemas.openxmlformats.org/package/2006/relationships',
}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters, row = m.group(1), int(m.group(2))
    col = 0
    for ch in letters:
        col = col * 26 + (ord(ch) - ord('A') + 1)
    return col, row

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("Archive entries:")
    for n in names:
        print("  ", n)

    wb_xml = ET.fromstring(z.read('xl/workbook.xml'))
    rels_xml = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))

    rid_to_target = {}
    for rel in rels_xml.findall('rel:Relationship', NS):
        rid_to_target[rel.get('Id')] = rel.get('Target')

    shared = []
    if 'xl/sharedStrings.xml' in names:
        ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss.findall('m:si', NS):
            shared.append(''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')))

    for sheet in wb_xml.findall('.//m:sheet', NS):
        name = sheet.get('name')
        rid = sheet.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        target = rid_to_target.get(rid, '')
        if not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        print(f"\n=== Sheet: {name} (file: {target}) ===")
        ws = ET.fromstring(z.read(target))
        for c in ws.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c'):
            ref = c.get('r')
            t = c.get('t')
            v = c.find('m:v', NS)
            if v is None:
                continue
            val = v.text
            if t == 's':
                val = shared[int(val)]
            elif t == 'str':
                pass
            elif t == 'b':
                val = val == '1'
            print(f"{ref}: {val!r}")

